18	namespace Atvoss::Reduce::Graph {
19	
20	using Atvoss::Util::Contains_v;
21	using Atvoss::Util::Map;
22	using Atvoss::Util::Unique_t;
23	
24	template <typename T>
25	static constexpr const T& Max(const T& a, const T& b)
26	{
27	    return a > b ? a : b;
28	}
29	
30	template <typename T>
31	static constexpr const T& Min(const T& a, const T& b)
32	{
33	    return a < b ? a : b;
34	}
