36	template <
37	    typename ExprList, typename ProcessedParams = TypeList<>, std::size_t pos = 0, std::size_t Size = Size_v<ExprList>>
38	struct InsertCopyIn {
39	private:
40	    using CurrentOpAssign = Get_t<ExprList, pos>;
41	    using InputsType = typename CurrentOpAssign::RhsType;
42	    using CurrentInputs = Unique_t<typename ExtractInputs<InputsType>::Type>;
43	
44	    template <typename InputNode>
45	    struct IsProcessed {
46	        static constexpr bool value = false;
47	    };
48	
49	    template <size_t N, typename T, ParamUsage U, size_t RN>
50	    struct IsProcessed<Param<N, T, U, RN>> {
51	        static constexpr bool value = Contains_v<ProcessedParams, Param<N, T, U, RN>>;
52	    };
53	
54	    template <typename InputNode>
55	    struct NeedInsertCopyIn {
56	        static constexpr bool value = IsInParam<InputNode>::value && !IsProcessed<InputNode>::value;
57	    };
58	
59	    template <typename InputNode>
60	    struct InsertCopyInIfNeeded {
61	        using Type = TypeList<>;
62	    };
63	
64	    template <size_t N, typename T, ParamUsage U, size_t RN>
65	    struct InsertCopyInIfNeeded<Param<N, T, U, RN>> {
66	        using Type = std::conditional_t<
67	            NeedInsertCopyIn<Param<N, T, U, RN>>::value,
68	            TypeList<OpAssign<Param<N, T, U, RN>, OpCopyIn<Param<N, T, U, RN>>>>, TypeList<>>;
69	    };
70	
71	    template <typename InputNode>
72	    struct ProcessInput {
73	        using Type = TypeList<>;
74	    };
75	
76	    template <size_t N, typename T, ParamUsage U, size_t RN>
77	    struct ProcessInput<Param<N, T, U, RN>> {
78	        using Type = typename InsertCopyInIfNeeded<Param<N, T, U, RN>>::Type;
79	    };
80	
81	    template <typename First, typename... Rest>
82	    struct ProcessInput<TypeList<First, Rest...>> {
83	        using FirstProcessed = typename ProcessInput<First>::Type;
84	        using RestProcessed = typename ProcessInput<TypeList<Rest...>>::Type;
85	        using Type = Concatenate_t<FirstProcessed, RestProcessed>;
86	    };
87	
88	    using InsertedOps = typename ProcessInput<CurrentInputs>::Type;
89	    using NewProcessedParams = Concatenate_t<ProcessedParams, CurrentInputs>;
90	
91	public:
92	    using Type = Concatenate_t<
93	        InsertedOps, TypeList<CurrentOpAssign>,
94	        typename InsertCopyIn<ExprList, NewProcessedParams, pos + 1, Size>::Type>;
95	};
