102	template <typename ExprList, std::size_t pos = 0, std::size_t Size = Size_v<ExprList>>
103	struct InsertCopyOut {
104	private:
105	    using CurrentOpAssign = Get_t<ExprList, pos>;
106	    using Output = typename CurrentOpAssign::LhsType;
107	
108	    using CopyOutOp =
109	        std::conditional_t<IsOutParam<Output>::value, TypeList<OpAssign<Output, OpCopyOut<Output>>>, TypeList<>>;
110	
111	public:
112	    using Type =
113	        Concatenate_t<TypeList<CurrentOpAssign>, CopyOutOp, typename InsertCopyOut<ExprList, pos + 1, Size>::Type>;
114	};
