127	template <typename ExprList>
128	struct DagBase {
129	public:
130	    // Collect all parameters used (Usage = In/InOut/Out)
131	    // REMEMBER:
132	    //  Size_v<AllParams> <= Size_v<InParams> + Size_v<OutParams>
133	    using AllParams = Params_t<ExprList>;
134	    // Collect CopyIn parameters (Usage = In/InOut)
135	    using InParams = Filter_t<IsInVar, AllParams>;
136	    // Collect CopyOut parameters (Usage = InOut/Out)
137	    using OutParams = Filter_t<IsOutVar, AllParams>;
138	};
