140	template <typename ExprList, typename FullList, typename ExcludeList, typename ResultList = TypeList<>>
141	struct FindLocalVarReferences;
142	
143	template <typename FullList, typename ExcludeList, typename... ResultTypes>
144	struct FindLocalVarReferences<TypeList<>, FullList, ExcludeList, TypeList<ResultTypes...>> {
145	    using Type = TypeList<ResultTypes...>;
146	    using OtherInputs = TypeList<>;
147	};
148	
149	template <typename First, typename... Rest, typename FullList, typename ExcludeList, typename... ResultTypes>
150	struct FindLocalVarReferences<TypeList<First, Rest...>, FullList, ExcludeList, TypeList<ResultTypes...>> {
151	public:
152	    using CurrentResults = TypeList<ResultTypes...>;
153	    using Output = typename First::LhsType;
154	    using DirectReferences = typename FilterRefLocalVar<FullList, Output>::Type;
155	    using NewExclude = Concatenate_t<ExcludeList, TypeList<Output>>;
156	
157	    using DirectOtherInputs = typename FindAllUnhandledInputs<DirectReferences, FullList, NewExclude>::Type;
158	    using NewExcludeForRecursive = Concatenate_t<NewExclude, Map_t<ExtractResultType, DirectOtherInputs>>;
159	
160	    using RecursiveRefResult = FindLocalVarReferences<DirectReferences, FullList, NewExcludeForRecursive>;
161	    using RecursiveResult = typename RecursiveRefResult::Type;
162	    using RecursiveOtherInputs = typename RecursiveRefResult::OtherInputs;
163	
164	    using DirectAndRecursiveOtherInputs = Concatenate_t<DirectOtherInputs, RecursiveOtherInputs>;
165	    using NewExcludeWithOtherInputs =
166	        Concatenate_t<NewExcludeForRecursive, Map_t<ExtractResultType, DirectAndRecursiveOtherInputs>>;
167	
168	    using NextRefResult =
169	        FindLocalVarReferences<TypeList<Rest...>, FullList, NewExcludeWithOtherInputs, CurrentResults>;
170	    using NextResult = typename NextRefResult::Type;
171	    using NextOtherInputs = typename NextRefResult::OtherInputs;
172	
173	    using CombinedOtherInputs = Concatenate_t<DirectAndRecursiveOtherInputs, NextOtherInputs>;
174	
175	    using RefsSoFar = Concatenate_t<DirectReferences, RecursiveResult, NextResult>;
176	
177	    using OtherInputRefs = typename CollectOtherInputRefs<
178	        CombinedOtherInputs, FullList, NewExcludeWithOtherInputs, Concatenate_t<RefsSoFar, CurrentResults>>::Type;
179	    using Type = Unique_t<OtherInputRefs>;
180	    using OtherInputs = Unique_t<CombinedOtherInputs>;
181	};
182	
183	template <typename ExprList /*TypeList*/, bool IsBinaryAcc>
184	struct ReduceAutoDag {
185	private:
186	    // Step 1: 识别 Reduce 操作
187	    using ReduceOpList = Filter_t<ContainsReduceOp, ExprList>;
188	    using ReduceOpResList = typename Map<ExtractResultType, ReduceOpList>::Type;
189	    // Step 2: 查找依赖 Reduce 输出的表达式
190	    using ReduceRefListRaw = typename FindLocalVarReferences<ReduceOpList, ExprList, ReduceOpResList>::Type;
191	    using ReduceRefList = typename SortExprsByOutput<ReduceRefListRaw>::Type;
192	    using ReduceRefCopyInList = typename InsertCopyIn<ReduceRefList>::Type;
193	    using ReducedWithReduceList = Concatenate_t<ReduceOpList, ReduceRefList>;
194	    using ReducedWithReduceCopyInList = Concatenate_t<ReduceOpList, ReduceRefCopyInList>;
195	    // Step 3: 划分 PreReduce 和 Reduced
196	    using PreReduceWithReduceList = Difference_t<ExprList, ReduceRefList>;
197	    using PreReduceWithReduceCopyInList = typename InsertCopyIn<PreReduceWithReduceList>::Type;
198	    using PreReduceWoReduceCopyInList = Difference_t<PreReduceWithReduceCopyInList, ReduceOpList>;
199	
200	public:
201	    using PreReduceList = typename InsertCopyOut<PreReduceWithReduceCopyInList>::Type;
202	    using ReducedList = typename InsertCopyOut<ReducedWithReduceCopyInList>::Type;
203	    using PreReduceBufGen = BufferIdGenerator<PreReduceWoReduceCopyInList, ReduceOpList, IsBinaryAcc>;
204	    using ReducedBufGen = BufferIdGenerator<ReducedWithReduceCopyInList, ReduceOpList, false>;
205	    static constexpr auto PreReduceBufIds = PreReduceBufGen::GetBufferIds();
206	    static constexpr auto ReducedBufIds = ReducedBufGen::GetBufferIds();
207	
208	private:
209	    using PreReduceBase = DagBase<PreReduceWithReduceList>;
210	    using ReducedBase = DagBase<ReducedWithReduceList>;
211	
212	    using PreReduceAllParams = typename PreReduceBase::AllParams;
213	    using PreReduceInParams = typename PreReduceBase::InParams;
214	    using PreReduceOutParams = typename PreReduceBase::OutParams;
215	    using ReducedAllParams = typename ReducedBase::AllParams;
216	    using ReducedInParams = typename ReducedBase::InParams;
217	    using ReducedOutParams = typename ReducedBase::OutParams;
218	
219	public:
220	    template <bool IsPre>
221	    __host_aicore__ constexpr static std::size_t GetMTE2Num()
222	    {
223	        if constexpr (IsPre) {
224	            return Size_v<PreReduceInParams>;
225	        } else {
226	            return Size_v<ReducedInParams>;
227	        }
228	    }
229	
230	    template <bool IsPre>
231	    __host_aicore__ constexpr static std::size_t GetMTE3Num()
232	    {
233	        if constexpr (IsPre) {
234	            return Size_v<PreReduceOutParams>;
235	        } else {
236	            return Size_v<ReducedOutParams>;
237	        }
238	    }
239	
240	    template <bool IsPre>
241	    __host_aicore__ constexpr static int32_t GetTempBufNum()
242	    {
243	        if constexpr (IsPre) {
244	            return PreReduceBufGen::GetTempCalcCount();
245	        } else {
246	            return ReducedBufGen::GetTempCalcCount();
247	        }
248	    }
249	
250	    template <bool IsPre>
251	    __host_aicore__ constexpr static int32_t GetInputMaxDTypeSize()
252	    {
253	        if constexpr (IsPre) {
254	            return PreReduceBufGen::GetInputMaxDTypeSize();
255	        } else {
256	            return ReducedBufGen::GetInputMaxDTypeSize();
257	        }
258	    }
259	
260	    template <bool IsPre>
261	    __host_aicore__ constexpr static int32_t GetInputMinDTypeSize()
262	    {
263	        if constexpr (IsPre) {
264	            return PreReduceBufGen::GetInputMinDTypeSize();
265	        } else {
266	            return ReducedBufGen::GetInputMinDTypeSize();
267	        }
268	    }
269	
270	    template <bool IsPre>
271	    __host_aicore__ constexpr static int32_t GetMaxDTypeSize()
272	    {
273	        if constexpr (IsPre) {
274	            return Max(
275	                Max(PreReduceBufGen::GetInputMaxDTypeSize(), PreReduceBufGen::GetOutputMaxDTypeSize()),
276	                PreReduceBufGen::GetLocalVarMaxDTypeSize());
277	        } else {
278	            return Max(
279	                Max(ReducedBufGen::GetInputMaxDTypeSize(), ReducedBufGen::GetOutputMaxDTypeSize()),
280	                ReducedBufGen::GetLocalVarMaxDTypeSize());
281	        }
282	    }
283	
284	    template <bool IsPre>
285	    __host_aicore__ constexpr static int32_t GetMinDTypeSize()
286	    {
287	        if constexpr (IsPre) {
288	            return Min(
289	                Min(PreReduceBufGen::GetInputMinDTypeSize(), PreReduceBufGen::GetOutputMinDTypeSize()),
290	                PreReduceBufGen::GetLocalVarMinDTypeSize());
291	        } else {
292	            return Min(
293	                Min(ReducedBufGen::GetInputMinDTypeSize(), ReducedBufGen::GetOutputMinDTypeSize()),
294	                ReducedBufGen::GetLocalVarMinDTypeSize());
