11	#ifndef ATVOSS_REDUCE_GRAPH_HELPER_H
12	#define ATVOSS_REDUCE_GRAPH_HELPER_H
13	
14	#include <cstdint>
15	#include "graph/expr_operations.h"
16	
17	namespace Atvoss::Reduce::Graph {
18	
19	using Atvoss::Graph::ContainsNodeInExpr;
20	using Atvoss::Graph::ExtractInputs;
21	using Atvoss::Util::Any_v;
22	using Atvoss::Util::Concatenate_t;
23	using Atvoss::Util::Contains_v;
24	using Atvoss::Util::Difference_t;
25	using Atvoss::Util::Filter_t;
26	using Atvoss::Util::Map_t;
27	using Atvoss::Util::Size_v;
28	using Atvoss::Util::Sort_t;
29	using Atvoss::Util::Unique_t;
30	
31	template <typename ExprList, typename TargetNode, std::size_t start, std::size_t current = 0>
32	struct IsNodeUsedAfter;
33	
34	template <typename TargetNode, std::size_t start, std::size_t current>
35	struct IsNodeUsedAfter<TypeList<>, TargetNode, start, current> {
36	    static constexpr bool value = false;
37	};
38	
39	template <typename First, typename... Rest, typename TargetNode, std::size_t start, std::size_t current>
40	struct IsNodeUsedAfter<TypeList<First, Rest...>, TargetNode, start, current> {
41	private:
42	    static constexpr bool needCheck = (current >= start);
43	    static constexpr bool currentCheck =
44	        needCheck ? ContainsNodeInExpr<typename First::RhsType, TargetNode>::value : false;
45	    static constexpr bool rest = IsNodeUsedAfter<TypeList<Rest...>, TargetNode, start, current + 1>::value;
46	
47	public:
48	    static constexpr bool value = currentCheck || rest;
49	};
50	
51	template <typename Expr>
52	struct ExtractResultType {
53	    using Type = typename Expr::LhsType;
54	};
55	
56	template <typename T, typename = void>
57	struct IsReduceOp : std::false_type {};
58	
59	template <typename T>
60	struct IsReduceOp<T, std::enable_if_t<std::is_base_of_v<ReduceOp<typename T::DataType>, T>>> : std::true_type {};
61	
62	template <typename T>
63	struct ContainsReduceOp : IsReduceOp<T> {};
64	
65	template <template <typename> class Op, typename Inner>
66	struct ContainsReduceOp<Op<Inner>> : std::bool_constant<IsReduceOp<Op<Inner>>::value> {};
67	
68	template <typename T, typename U>
69	struct ContainsReduceOp<OpAssign<T, U>> : ContainsReduceOp<U> {};
70	
71	template <typename TargetNode>
72	struct ContainsNodeInRefList {
73	    template <typename Op>
74	    struct Type {
75	        static constexpr bool value = ContainsNodeInExpr<Op, TargetNode>::value;
76	    };
77	};
78	
79	template <typename ReduceOpList, typename TargetLocalVar>
80	struct CheckReduceInput {
81	    static constexpr bool value = Any_v<ContainsNodeInRefList<TargetLocalVar>::template Type, ReduceOpList>;
82	};
83	
84	template <typename ReduceOpList, typename CurrentOpAssign>
85	struct IsDirectConnectToReduce {
86	    using CurrentOutput = typename CurrentOpAssign::LhsType;
87	    static constexpr bool value = CheckReduceInput<ReduceOpList, CurrentOutput>::value;
88	};
89	
90	template <typename List, typename TargetNode>
91	struct FilterRefLocalVar {
92	    using Type = Filter_t<ContainsNodeInRefList<TargetNode>::template Type, List>;
93	};
94	
95	template <typename List, typename ExcludeList>
96	struct FilterNotInExclude {
97	    template <typename T>
98	    struct NotInExclude : std::bool_constant<!Contains_v<ExcludeList, T>> {};
99	    using Type = Filter_t<NotInExclude, List>;
100	};
101	
102	// 找到不在CollectedExprs中，定义输入(父节点)的表达式
103	template <typename Inputs, typename FullList, typename CollectedExprs = TypeList<>, typename Result = TypeList<>>
104	struct FindUnhandledInputsExpr;
105	
106	template <typename Inputs, typename CollectedExprs, typename... ResultTypes>
107	struct FindUnhandledInputsExpr<Inputs, TypeList<>, CollectedExprs, TypeList<ResultTypes...>> {
108	    using Type = TypeList<ResultTypes...>;
109	};
110	
111	template <typename Inputs, typename FirstExpr, typename... RestExpr, typename CollectedExprs, typename... ResultTypes>
112	struct FindUnhandledInputsExpr<Inputs, TypeList<FirstExpr, RestExpr...>, CollectedExprs, TypeList<ResultTypes...>> {
113	private:
114	    using CurrentResults = TypeList<ResultTypes...>;
115	    using LHS = typename FirstExpr::LhsType;
116	    static constexpr bool IsLocalVarInput = Contains_v<Inputs, LHS>;
117	    static constexpr bool NotCollected = !Contains_v<CollectedExprs, FirstExpr>;
118	    using NeedAdd = std::conditional_t<IsLocalVarInput && NotCollected, std::true_type, std::false_type>;
119	    using NewResult =
120	        std::conditional_t<NeedAdd::value, Concatenate_t<CurrentResults, TypeList<FirstExpr>>, CurrentResults>;
121	    using NewCollected =
122	        std::conditional_t<NeedAdd::value, Concatenate_t<CollectedExprs, TypeList<FirstExpr>>, CollectedExprs>;
123	
124	public:
125	    using Type = typename FindUnhandledInputsExpr<Inputs, TypeList<RestExpr...>, NewCollected, NewResult>::Type;
126	};
127	
128	template <typename ExprList, typename FullList, typename ExcludeList, typename Result = TypeList<>>
129	struct FindAllUnhandledInputs;
130	
131	template <typename FullList, typename ExcludeList, typename... ResultTypes>
132	struct FindAllUnhandledInputs<TypeList<>, FullList, ExcludeList, TypeList<ResultTypes...>> {
133	    using Type = TypeList<ResultTypes...>;
134	};
135	
136	template <typename First, typename... Rest, typename FullList, typename ExcludeList, typename... ResultTypes>
137	struct FindAllUnhandledInputs<TypeList<First, Rest...>, FullList, ExcludeList, TypeList<ResultTypes...>> {
138	private:
139	    using CurrentResults = TypeList<ResultTypes...>;
140	    using Inputs = typename ExtractInputs<typename First::RhsType>::Type;
141	    using FilteredInputs = typename FilterNotInExclude<Inputs, ExcludeList>::Type;
142	    using NewExprs = typename FindUnhandledInputsExpr<FilteredInputs, FullList, CurrentResults>::Type;
143	    using CombinedResult = Concatenate_t<CurrentResults, NewExprs>;
144	
145	public:
146	    using Type = typename FindAllUnhandledInputs<TypeList<Rest...>, FullList, ExcludeList, CombinedResult>::Type;
147	};
148	
149	// 找到不在CollectedExprs中，引用输出(子节点)的表达式
150	template <typename VarList, typename FullList, typename CollectedExprs = TypeList<>, typename Result = TypeList<>>
151	struct FindOutputRefsExpr;
152	
153	template <typename FullList, typename CollectedExprs, typename... ResultTypes>
154	struct FindOutputRefsExpr<TypeList<>, FullList, CollectedExprs, TypeList<ResultTypes...>> {
155	    using Type = TypeList<ResultTypes...>;
156	};
157	
158	template <typename FirstVar, typename... RestVars, typename FullList, typename CollectedExprs, typename... ResultTypes>
159	struct FindOutputRefsExpr<TypeList<FirstVar, RestVars...>, FullList, CollectedExprs, TypeList<ResultTypes...>> {
160	private:
161	    using CurrentRefs = typename FilterRefLocalVar<FullList, FirstVar>::Type;
162	    using FilteredCurrentRefs = Difference_t<CurrentRefs, CollectedExprs>;
163	    using NewCollected = Concatenate_t<CollectedExprs, FilteredCurrentRefs>;
164	    using NewResult = Concatenate_t<TypeList<ResultTypes...>, FilteredCurrentRefs>;
165	
166	public:
167	    using Type = typename FindOutputRefsExpr<TypeList<RestVars...>, FullList, NewCollected, NewResult>::Type;
168	};
169	
170	template <typename Expr>
171	struct GetExprOutputNumber;
172	
173	template <typename LHS, typename RHS>
174	struct GetExprOutputNumber<OpAssign<LHS, RHS>> {
175	    static constexpr std::size_t value = LHS::number;
176	};
177	
178	template <typename Expr>
179	struct IsExprOutputParam : std::false_type {};
180	
181	template <typename LHS, typename RHS>
182	struct IsExprOutputParam<OpAssign<LHS, RHS>> : Atvoss::IsParam<LHS> {};
183	
184	// 表达式按其输出类型LocalVar、Param排序，LocalVar在前，Param在后，且LocalVar按number排序
185	template <typename ExprList>
186	struct SortExprsByOutput;
187	
188	template <typename... Exprs>
189	struct SortExprsByOutput<TypeList<Exprs...>> {
190	    template <typename E1, typename E2>
191	    struct ExprOrderLess {
192	        static constexpr bool E1IsParam = IsExprOutputParam<E1>::value;
193	        static constexpr bool E2IsParam = IsExprOutputParam<E2>::value;
194	        static constexpr bool value =
195	            (!E1IsParam && E2IsParam) ||
196	            (!E1IsParam && !E2IsParam && GetExprOutputNumber<E1>::value < GetExprOutputNumber<E2>::value);
197	    };
198	    using Type = Sort_t<ExprOrderLess, TypeList<Exprs...>>;
199	};
200	
201	// 收集多输入场景下，分支输入的输入输出(父子节点)表达式
202	template <typename OtherInputsList, typename FullList, typename ExcludeList, typename Result = TypeList<>>
203	struct CollectOtherInputRefs;
204	
205	template <typename FullList, typename ExcludeList, typename... ResultTypes>
206	struct CollectOtherInputRefs<TypeList<>, FullList, ExcludeList, TypeList<ResultTypes...>> {
207	    using Type = TypeList<ResultTypes...>;
208	};
209	
210	template <typename First, typename... Rest, typename FullList, typename ExcludeList, typename... ResultTypes>
211	struct CollectOtherInputRefs<TypeList<First, Rest...>, FullList, ExcludeList, TypeList<ResultTypes...>> {
212	private:
213	    using CurrentResults = TypeList<ResultTypes...>;
214	    using Inputs = typename ExtractInputs<typename First::RhsType>::Type;
215	    using FilteredInputs = typename FilterNotInExclude<Inputs, ExcludeList>::Type;
216	    using InputsDefExprs = typename FindUnhandledInputsExpr<FilteredInputs, FullList, CurrentResults>::Type;
217	
218	    // 单输出多引用场景
219	    using Output = typename First::LhsType;
220	    using OutputRefExprs = typename FindOutputRefsExpr<TypeList<Output>, FullList, CurrentResults>::Type;
221	    using NodeInOutExprs = Concatenate_t<InputsDefExprs, OutputRefExprs>;
222	    // 按照输入 + 当前节点 + 输出的顺序排列
223	    using NextResult = Concatenate_t<InputsDefExprs, TypeList<First>, OutputRefExprs, CurrentResults>;
224	    using ResultList = Map_t<ExtractResultType, NodeInOutExprs>;
225	    using NestExclude = Concatenate_t<ExcludeList, ResultList>;
226	    using NestRest = Unique_t<Concatenate_t<NodeInOutExprs, TypeList<Rest...>>>;
227	
228	public:
229	    using Type = typename CollectOtherInputRefs<NestRest, FullList, NestExclude, NextResult>::Type;
230	};
231	
232	} // namespace Atvoss::Reduce::Graph
233	
234	#endif

