36	template <>
37	struct CollectAllInputs<TypeList<>> {
38	    using Type = TypeList<>;
39	};
40	
41	template <typename First, typename... Rest>
42	struct CollectAllInputs<TypeList<First, Rest...>> {
43	private:
44	    using FirstInputs = typename ExtractInputs<typename First::RhsType>::Type;
45	    using RestInputs = typename CollectAllInputs<TypeList<Rest...>>::Type;
46	
47	public:
48	    using Type = Concatenate_t<FirstInputs, RestInputs>;
49	};
50	
51	template <typename ExprList>
52	constexpr std::size_t UniqueReduceInputCount_v = Size_v<Unique_t<typename CollectAllInputs<ExprList>::Type>>;
53	
54	constexpr static uint32_t BUF_PARAM = 0b001;
55	constexpr static uint32_t BUF_LOCAL_VAR = 0b010;
56	constexpr static uint32_t BUF_REDUCE_VAR = 0b100;
57	
58	constexpr std::size_t INIT_MAX_DTYPE_SIZE = 1UL;
59	constexpr std::size_t INIT_MIN_DTYPE_SIZE = 8UL;
60	
61	template <typename ExprList, std::size_t pos>
62	struct CanRelease {
63	    template <typename Node>
64	    struct Type {
65	        static constexpr bool value = IsNodeUsedAfter<ExprList, Node, pos + 1, 0>::value == false;
66	    };
67	};
68	
69	template <int32_t bufId, uint32_t bufUsage>
70	struct BufferWrapper {
71	    constexpr static int32_t bufferId = bufId;
72	    constexpr static uint32_t bufferUsage = bufUsage;
73	};
74	
75	template <typename Node, typename BufferMap>
76	struct GetBufferId {
77	    static constexpr int32_t value = -1;
78	    static constexpr uint32_t usage = 0;
79	};
80	
81	template <size_t N, typename T, ParamUsage U, size_t RN, typename BufWrapper>
82	struct GetBufferId<Param<N, T, U, RN>, TypeList<Param<N, T, U, RN>, BufWrapper>> {
83	    static constexpr int32_t value = BufWrapper::bufferId;
84	    static constexpr uint32_t usage = BufWrapper::bufferUsage;
85	};
86	
87	template <size_t N, typename T, typename L, typename BufWrapper>
88	struct GetBufferId<LocalVar<N, T, L>, TypeList<LocalVar<N, T, L>, BufWrapper>> {
89	    static constexpr int32_t value = BufWrapper::bufferId;
90	    static constexpr uint32_t usage = BufWrapper::bufferUsage;
91	};
92	
93	template <typename Node, typename First, typename BufWrapper, typename... Rest>
94	struct GetBufferId<Node, TypeList<First, BufWrapper, Rest...>> {
95	    static constexpr int32_t value = GetBufferId<Node, TypeList<Rest...>>::value;
96	    static constexpr uint32_t usage = GetBufferId<Node, TypeList<Rest...>>::usage;
97	};
98	
99	template <typename LHS>
100	struct GetBufferUsage {
101	    static constexpr uint32_t value = BUF_LOCAL_VAR;
102	};
103	
104	template <size_t N, typename T, ParamUsage U, size_t RN>
105	struct GetBufferUsage<Param<N, T, U, RN>> {
106	    static constexpr uint32_t value = BUF_PARAM;
107	};
108	
109	template <typename BufferPool, int32_t BufId>
110	struct RemoveFromPool {
111	    using Type = BufferPool;
112	};
113	
114	template <int32_t BufId, int32_t FirstVal, typename... Rest>
115	struct RemoveFromPool<TypeList<std::integral_constant<int32_t, FirstVal>, Rest...>, BufId> {
116	    using Type = std::conditional_t<
117	        FirstVal == BufId, TypeList<Rest...>,
118	        Append_t<typename RemoveFromPool<TypeList<Rest...>, BufId>::Type, std::integral_constant<int32_t, FirstVal>>>;
119	};
120	
121	template <int32_t BufId>
122	struct RemoveFromPool<TypeList<>, BufId> {
123	    using Type = TypeList<>;
124	};
125	
126	template <typename FreeBufferPool, typename BufferMap, typename InputNodeList, typename ExprList, std::size_t opPos>
127	struct ReleaseCurrentInputs {
128	    using Type = FreeBufferPool;
129	};
130	
131	template <
132	    typename First, typename... Rest, typename FreeBufferPool, typename BufferMap, typename ExprList, std::size_t opPos>
133	struct ReleaseCurrentInputs<FreeBufferPool, BufferMap, TypeList<First, Rest...>, ExprList, opPos> {
134	private:
135	    static constexpr bool canRelease = CanRelease<ExprList, opPos>::template Type<First>::value;
136	    static constexpr int32_t bufferId = GetBufferId<First, BufferMap>::value;
137	    static constexpr uint32_t bufferUsage = GetBufferId<First, BufferMap>::usage;
138	    static constexpr bool isLocalVar = bufferUsage == BUF_LOCAL_VAR;
139	    static constexpr bool canAddToPool = canRelease && isLocalVar && bufferId >= 0;
140	    using RestType = typename ReleaseCurrentInputs<FreeBufferPool, BufferMap, TypeList<Rest...>, ExprList, opPos>::Type;
141	
142	public:
143	    using Type =
144	        std::conditional_t<canAddToPool, Append_t<RestType, std::integral_constant<int32_t, bufferId>>, RestType>;
145	};
146	
147	template <typename FreeBufferPool, typename BufferMap, typename ExprList, std::size_t opPos>
148	struct ReleaseCurrentInputs<FreeBufferPool, BufferMap, TypeList<>, ExprList, opPos> {
149	    using Type = FreeBufferPool;
150	};
151	
152	template <
153	    typename ExprList, typename ReduceOpList, bool IsBinaryAcc, typename BufferMap, typename FreeBufferPool,
154	    std::size_t StartBufIdForLocalVar, std::size_t InputParamMaxDTypeSize = INIT_MAX_DTYPE_SIZE,
155	    std::size_t InputParamMinDTypeSize = INIT_MIN_DTYPE_SIZE, std::size_t OutputParamMaxDTypeSize = INIT_MAX_DTYPE_SIZE,
156	    std::size_t OutputParamMinDTypeSize = INIT_MIN_DTYPE_SIZE, std::size_t LocalVarMaxDTypeSize = INIT_MAX_DTYPE_SIZE,
157	    std::size_t LocalVarMinDTypeSize = INIT_MIN_DTYPE_SIZE, std::size_t opPos = 0, std::size_t nextParamBufId = 0,
158	    std::size_t nextLocalBufId = StartBufIdForLocalVar, typename AllocList = TypeList<>,
159	    std::size_t Size = Size_v<ExprList>>
160	struct GenerateBufferIdOrderAux {
161	private:
162	    using CurrentOpAssign = Get_t<ExprList, opPos>;
163	    using LHS = typename CurrentOpAssign::LhsType;
164	    using RHS = typename CurrentOpAssign::RhsType;
165	    using CurrentInputs = typename ExtractInputs<RHS>::Type;
166	
167	    static_assert(GetBufferId<LHS, BufferMap>::value < 0, "Duplicate output in different expressions");
168	
169	    constexpr static bool IsLocalVarBuffer()
170	    {
171	        return GetBufferUsage<LHS>::value == BUF_LOCAL_VAR;
172	    }
173	
174	    constexpr static bool IsReduceVarBuffer()
175	    {
176	        return IsBinaryAcc && IsLocalVarBuffer() && IsDirectConnectToReduce<ReduceOpList, CurrentOpAssign>::value;
177	    }
178	
179	    constexpr static bool NeedsDoubleBuffer()
180	    {
181	        return !IsLocalVarBuffer() || IsReduceVarBuffer();
182	    }
183	
184	    constexpr static bool CanReuseBuffer()
185	    {
186	        return IsLocalVarBuffer() && !IsReduceVarBuffer();
187	    }
188	
189	    constexpr static bool HasFreeBuffer()
190	    {
191	        return Size_v<FreeBufferPool> > 0;
192	    }
193	
194	    constexpr static std::size_t GetDTypeSize()
195	    {
196	        return sizeof(typename LHS::Type::PrimType);
197	    }
198	
199	    constexpr static bool IsInputParam()
200	    {
201	        if constexpr (IsLocalVarBuffer()) {
202	            return false;
203	        } else {
204	            return LHS::usage == ParamUsage::IN || LHS::usage == ParamUsage::IN_OUT;
205	        }
206	    }
207	
208	    constexpr static bool IsOutputParam()
209	    {
210	        if constexpr (IsLocalVarBuffer()) {
211	            return false;
212	        } else {
213	            return LHS::usage == ParamUsage::OUT || LHS::usage == ParamUsage::IN_OUT;
214	        }
215	    }
216	
217	    constexpr static std::size_t UpdateInputParamMaxDTypeSize()
218	    {
219	        if constexpr (IsInputParam()) {
220	            return (GetDTypeSize() > InputParamMaxDTypeSize) ? GetDTypeSize() : InputParamMaxDTypeSize;
221	        } else {
222	            return InputParamMaxDTypeSize;
223	        }
224	    }
225	
226	    constexpr static std::size_t UpdateInputParamMinDTypeSize()
227	    {
228	        if constexpr (IsInputParam()) {
229	            return (GetDTypeSize() < InputParamMinDTypeSize) ? GetDTypeSize() : InputParamMinDTypeSize;
230	        } else {
231	            return InputParamMinDTypeSize;
232	        }
233	    }
234	
235	    constexpr static std::size_t UpdateOutputParamMaxDTypeSize()
236	    {
237	        if constexpr (IsOutputParam()) {
238	            return (GetDTypeSize() > OutputParamMaxDTypeSize) ? GetDTypeSize() : OutputParamMaxDTypeSize;
239	        } else {
240	            return OutputParamMaxDTypeSize;
241	        }
242	    }
243	
244	    constexpr static std::size_t UpdateOutputParamMinDTypeSize()
245	    {
246	        if constexpr (IsOutputParam()) {
247	            return (GetDTypeSize() < OutputParamMinDTypeSize) ? GetDTypeSize() : OutputParamMinDTypeSize;
248	        } else {
249	            return OutputParamMinDTypeSize;
250	        }
251	    }
252	
253	    constexpr static std::size_t UpdateLocalVarMaxDTypeSize()
254	    {
255	        if constexpr (IsLocalVarBuffer()) {
256	            return (GetDTypeSize() > LocalVarMaxDTypeSize) ? GetDTypeSize() : LocalVarMaxDTypeSize;
257	        } else {
258	            return LocalVarMaxDTypeSize;
259	        }
260	    }
261	
262	    constexpr static std::size_t UpdateLocalVarMinDTypeSize()
263	    {
264	        if constexpr (IsLocalVarBuffer()) {
265	            return (GetDTypeSize() < LocalVarMinDTypeSize) ? GetDTypeSize() : LocalVarMinDTypeSize;
266	        } else {
267	            return LocalVarMinDTypeSize;
268	        }
269	    }
270	
271	    constexpr static int32_t AllocBufferId()
272	    {
273	        if constexpr (NeedsDoubleBuffer()) {
274	            return static_cast<int32_t>(nextParamBufId);
275	        } else {
276	            if constexpr (CanReuseBuffer() && HasFreeBuffer()) {
277	                return Get_t<FreeBufferPool, 0>::value;
278	            } else {
279	                return static_cast<int32_t>(nextLocalBufId);
280	            }
281	        }
282	    }
283	
284	    constexpr static uint32_t GetAllocBufferUsage()
285	    {
286	        if constexpr (IsReduceVarBuffer()) {
287	            return BUF_REDUCE_VAR;
288	        } else {
289	            return GetBufferUsage<LHS>::value;
290	        }
291	    }
292	
293	    constexpr static std::size_t GetNextParamBufId()
294	    {
295	        if constexpr (NeedsDoubleBuffer()) {
296	            return nextParamBufId + 1;
297	        } else {
298	            return nextParamBufId;
299	        }
300	    }
301	
302	    constexpr static std::size_t GetNextLocalBufId()
303	    {
304	        if constexpr (!NeedsDoubleBuffer()) {
305	            if constexpr (CanReuseBuffer() && HasFreeBuffer()) {
306	                return nextLocalBufId;
307	            } else {
308	                return nextLocalBufId + 1;
309	            }
310	        } else {
311	            return nextLocalBufId;
312	        }
313	    }
314	
315	    constexpr static auto UpdateFreePoolAfterAlloc()
316	    {
317	        if constexpr (!NeedsDoubleBuffer() && CanReuseBuffer() && HasFreeBuffer()) {
318	            return typename RemoveFromPool<FreeBufferPool, AllocBufferId()>::Type{};
319	        } else {
320	            return FreeBufferPool{};
321	        }
322	    }
323	
324	    using NextFreeBufferPool = decltype(UpdateFreePoolAfterAlloc());
325	    using Buf = BufferWrapper<AllocBufferId(), GetAllocBufferUsage()>;
326	    using NextAllocList = Append_t<AllocList, Buf>;
327	    using NestBufferMap = Concatenate_t<BufferMap, TypeList<LHS, Buf>>;
328	    using UpdatedFreePool =
329	        typename ReleaseCurrentInputs<NextFreeBufferPool, NestBufferMap, CurrentInputs, ExprList, opPos>::Type;
330	
331	    using NextResult = GenerateBufferIdOrderAux<
332	        ExprList, ReduceOpList, IsBinaryAcc, NestBufferMap, UpdatedFreePool, StartBufIdForLocalVar,
333	        UpdateInputParamMaxDTypeSize(), UpdateInputParamMinDTypeSize(), UpdateOutputParamMaxDTypeSize(),
334	        UpdateOutputParamMinDTypeSize(), UpdateLocalVarMaxDTypeSize(), UpdateLocalVarMinDTypeSize(), opPos + 1,
335	        GetNextParamBufId(), GetNextLocalBufId(), NextAllocList, Size>;
336	
337	public:
338	    using Type = typename NextResult::Type;
339	    using BufferMapType = typename NextResult::BufferMapType;
340	
341	    static constexpr std::size_t InputParamMaxDTypeSizeValue = NextResult::InputParamMaxDTypeSizeValue;
342	    static constexpr std::size_t InputParamMinDTypeSizeValue = NextResult::InputParamMinDTypeSizeValue;
343	    static constexpr std::size_t OutputParamMaxDTypeSizeValue = NextResult::OutputParamMaxDTypeSizeValue;
344	    static constexpr std::size_t OutputParamMinDTypeSizeValue = NextResult::OutputParamMinDTypeSizeValue;
345	    static constexpr std::size_t LocalVarMaxDTypeSizeValue = NextResult::LocalVarMaxDTypeSizeValue;
346	    static constexpr std::size_t LocalVarMinDTypeSizeValue = NextResult::LocalVarMinDTypeSizeValue;
347	};
348	
349	template <
350	    typename ExprList, typename ReduceOpList, bool IsBinaryAcc, typename BufferMap, typename FreeBufferPool,
351	    std::size_t StartBufIdForLocalVar, std::size_t InputParamMaxDTypeSize, std::size_t InputParamMinDTypeSize,
352	    std::size_t OutputParamMaxDTypeSize, std::size_t OutputParamMinDTypeSize, std::size_t LocalVarMaxDTypeSize,
353	    std::size_t LocalVarMinDTypeSize, std::size_t nextParamBufId, std::size_t nextLocalBufId, typename AllocList,
354	    std::size_t Size>
355	struct GenerateBufferIdOrderAux<
356	    ExprList, ReduceOpList, IsBinaryAcc, BufferMap, FreeBufferPool, StartBufIdForLocalVar, InputParamMaxDTypeSize,
357	    InputParamMinDTypeSize, OutputParamMaxDTypeSize, OutputParamMinDTypeSize, LocalVarMaxDTypeSize,
358	    LocalVarMinDTypeSize, Size, nextParamBufId, nextLocalBufId, AllocList, Size> {
359	    using Type = AllocList;
360	    using BufferMapType = BufferMap;
361	    static constexpr std::size_t InputParamMaxDTypeSizeValue = InputParamMaxDTypeSize;
362	    static constexpr std::size_t InputParamMinDTypeSizeValue = InputParamMinDTypeSize;
363	    static constexpr std::size_t OutputParamMaxDTypeSizeValue = OutputParamMaxDTypeSize;
364	    static constexpr std::size_t OutputParamMinDTypeSizeValue = OutputParamMinDTypeSize;
365	    static constexpr std::size_t LocalVarMaxDTypeSizeValue = LocalVarMaxDTypeSize;
366	    static constexpr std::size_t LocalVarMinDTypeSizeValue = LocalVarMinDTypeSize;
367	};
368	
369	template <typename AllocList>
370	struct MaxBufferId;
371	
372	template <>
373	struct MaxBufferId<TypeList<>> {
374	    static constexpr int32_t value = -1;
375	};
376	
377	template <typename First, typename... Rest>
378	struct MaxBufferId<TypeList<First, Rest...>> {
379	    static constexpr int32_t current = First::bufferId;
380	    static constexpr int32_t rest = MaxBufferId<TypeList<Rest...>>::value;
381	    static constexpr int32_t value = (current > rest) ? current : rest;
382	};
383	
384	template <typename AllocList, typename Ids = TypeList<>>
385	struct TempCalcCount;
386	
387	template <typename Ids>
388	struct TempCalcCount<TypeList<>, Ids> {
389	    static constexpr std::size_t value = 0;
390	};
391	
392	template <typename First, typename... Rest, typename Ids>
393	struct TempCalcCount<TypeList<First, Rest...>, Ids> {
394	    static constexpr bool isLocalVar = First::bufferUsage != BUF_PARAM;
395	    static constexpr int32_t bufId = First::bufferId;
396	    static constexpr bool exist = Contains_v<Ids, std::integral_constant<int32_t, bufId>>;
397	    static constexpr bool needCount = isLocalVar && !exist;
398	    using NewIds = std::conditional_t<needCount, Append_t<Ids, std::integral_constant<int32_t, bufId>>, Ids>;
399	    static constexpr std::size_t current = needCount ? 1 : 0;
400	    static constexpr std::size_t rest = TempCalcCount<TypeList<Rest...>, NewIds>::value;
401	    static constexpr std::size_t value = current + rest;
402	};
403	
404	template <int32_t bufferId, uint32_t bufferUsage, uint32_t pongOffset>
405	static constexpr int32_t CalcPongBufferId()
406	{
407	    if constexpr (bufferUsage == BUF_LOCAL_VAR) {
408	        return bufferId;
409	    } else {
410	        return bufferId + pongOffset;
411	    }
412	}
413	
414	template <typename AllocList, uint32_t pongOffset>
415	struct ExtractBufferId {};
416	
417	template <typename... Ts, uint32_t pongOffset>
418	struct ExtractBufferId<TypeList<Ts...>, pongOffset> {
419	    static constexpr size_t size = sizeof...(Ts);
420	    constexpr static int32_t arr[2][size] = {
421	        {Ts::bufferId...}, {CalcPongBufferId<Ts::bufferId, Ts::bufferUsage, pongOffset>()...}};
422	    constexpr static const int32_t* Value[2] = {arr[0], arr[1]};
423	};
424	
425	template <typename ExprList, typename ReduceOpList = TypeList<>, bool IsBinaryAcc = true>
426	struct BufferIdGenerator {
427	private:
428	    static constexpr bool IsSingleExprNoBinaryAcc = (Size_v<ExprList> == 1) && !IsBinaryAcc;
429	    static constexpr std::size_t ResultParamCount = Size_v<Params_t<Map_t<ExtractResultType, ExprList>>>;
430	    static constexpr std::size_t StartBufIdForLocalVar =
431	        IsSingleExprNoBinaryAcc ?
432	            1 :
433	            (IsBinaryAcc ? ResultParamCount + UniqueReduceInputCount_v<ReduceOpList> : ResultParamCount);
434	
435	    using AuxResult =
436	        GenerateBufferIdOrderAux<ExprList, ReduceOpList, IsBinaryAcc, TypeList<>, TypeList<>, StartBufIdForLocalVar>;
437	
438	    using AllocList = std::conditional_t<
439	        IsSingleExprNoBinaryAcc, TypeList<BufferWrapper<0, BUF_PARAM>, BufferWrapper<1, BUF_PARAM>>,
440	        std::conditional_t<
441	            Size_v<ExprList> == 1,
442	            TypeList<BufferWrapper<0, BUF_PARAM>, BufferWrapper<StartBufIdForLocalVar, BUF_LOCAL_VAR>>,
443	            typename AuxResult::Type>>;
444	
445	    static constexpr int32_t maxBufferId = MaxBufferId<AllocList>::value;
446	    static constexpr std::size_t tempCalcCount = TempCalcCount<AllocList>::value;
447	
448	    static constexpr int32_t singleExprNoBinaryAccArr[2][2] = {{0, 1}, {1, 0}};
449	    static constexpr const int32_t* singleExprNoBinaryAccBufferIds[2] = {
450	        singleExprNoBinaryAccArr[0], singleExprNoBinaryAccArr[1]};
451	
452	public:
453	    static constexpr size_t size = Size_v<AllocList>;
454	    static constexpr int32_t maxId = maxBufferId;
455	    static constexpr uint32_t offset = static_cast<uint32_t>(maxBufferId + 1);
456	    static constexpr std::size_t tempCalcNum = tempCalcCount;
457	
458	    using BufferMapType = typename AuxResult::BufferMapType;
459	
460	    static constexpr std::size_t InputParamMaxDTypeSize = AuxResult::InputParamMaxDTypeSizeValue;
461	    static constexpr std::size_t InputParamMinDTypeSize = AuxResult::InputParamMinDTypeSizeValue;
462	    static constexpr std::size_t OutputParamMaxDTypeSize = AuxResult::OutputParamMaxDTypeSizeValue;
463	    static constexpr std::size_t OutputParamMinDTypeSize = AuxResult::OutputParamMinDTypeSizeValue;
464	    static constexpr std::size_t LocalVarMaxDTypeSize = AuxResult::LocalVarMaxDTypeSizeValue;
465	    static constexpr std::size_t LocalVarMinDTypeSize = AuxResult::LocalVarMinDTypeSizeValue;
466	
467	    static constexpr BufferIdGenerator GetInstance()
468	    {
469	        return BufferIdGenerator{};
470	    }
471	
472	    static constexpr const int32_t* const* GetBufferIds()
473	    {
474	        if constexpr (IsSingleExprNoBinaryAcc) {
475	            return singleExprNoBinaryAccBufferIds;
476	        } else {
477	            return ExtractBufferId<AllocList, maxBufferId + 1>::Value;
478	        }
479	    }
480	
481	    static constexpr int32_t GetTempCalcCount()
482	    {
483	        return tempCalcCount;
484	    }
485	
486	    static constexpr size_t GetInputMaxDTypeSize()
487	    {
488	        return AuxResult::InputParamMaxDTypeSizeValue;
489	    }
490	
491	    static constexpr size_t GetInputMinDTypeSize()
492	    {
493	        return AuxResult::InputParamMinDTypeSizeValue;
494	    }
495	
496	    static constexpr size_t GetOutputMaxDTypeSize()
497	    {
498	        return AuxResult::OutputParamMaxDTypeSizeValue;
499	    }
500	
501	    static constexpr size_t GetOutputMinDTypeSize()
502	    {
503	        return AuxResult::OutputParamMinDTypeSizeValue;
504	    }
505	
506	    static constexpr size_t GetLocalVarMaxDTypeSize()
507	    {
508	        return AuxResult::LocalVarMaxDTypeSizeValue;
509	    }
510	
511	    static constexpr size_t GetLocalVarMinDTypeSize()
512	    {
513	        return AuxResult::LocalVarMinDTypeSizeValue;
514	    }
515	};
516	
517	} // namespace Atvoss::Reduce::Graph
518	#endif
