242	__host_aicore__ constexpr decltype(auto) ChangeInplaceParamUsageToIn()
243	{
244	    if constexpr (Size_v<InplaceParams> == 0) {
245	        return ExprList{};
246	    } else if constexpr (pos < Size_v<ExprList>) {
247	        using AssignExpr = Get_t<ExprList, pos>;
248	        using Lhs = typename AssignExpr::LhsType;
249	        using Rhs = typename AssignExpr::RhsType;
250	        using NewLhs =
251	            std::conditional_t<IsInplaceParam<Lhs>::value, Param<Lhs::number, typename Lhs::Type, ParamUsage::IN>, Lhs>;
252	        using NewRhs = ReplaceOpArgs_t<Rhs, InplaceParamUsageEditer::Type>;
253	        using NewAssign = OpAssign<NewLhs, NewRhs>;
254	        using ExprListNext = Set_t<ExprList, pos, NewAssign>;
255	        return ChangeInplaceParamUsageToIn<InplaceParams, ExprListNext, pos + 1>();
256	    } else {
257	        return ExprList{};
258	    }
259	}
260	
261	template <typename ExprList>
262	struct InplaceParamsProcessor {
263	private:
264	    using OriAllParams = Params_t<ExprList>;
265	    using InplaceParams = Filter_t<IsInplaceVar, OriAllParams>;
266	    using AssignedInplaceParams =
267	        Unique_t<decltype(ForEach(ExprList{}, ExtractAssignedParams<ParamUsage::IN_OUT>{}, TypeList<>{}))>;
268	    using ReplaceParamsMap =
269	        decltype(CreateReplacerForInplaceParams<AssignedInplaceParams, Size_v<OriAllParams> + 1>());
270	    using NewExprListTmp =
271	        decltype(ReplaceInplaceParam<AssignedInplaceParams, ReplaceParamsMap, ExprList, Size_v<OriAllParams> + 1>());
272	
273	public:
274	    using Type = decltype(ChangeInplaceParamUsageToIn<InplaceParams, NewExprListTmp>());
275	};
276	
277	template <int32_t targetBufId>
278	struct BufId2ParamFinder {
279	    template <typename M>
280	    struct Apply : std::bool_constant<First_t<M>::value == targetBufId> {};
281	};
282	
283	template <typename BufId2ParamMap, int32_t combinedBufId, typename Param>
284	struct UpdateBufId2Param {
285	private:
286	    constexpr static auto bufIds = DecodeBufferId<combinedBufId>::Value;
287	    constexpr static auto outBufId = bufIds[0];
288	    constexpr static auto pos = Find_v<BufId2ParamFinder<outBufId>::template Apply, BufId2ParamMap>;
289	    using NewItem = TypeList<std::integral_constant<int32_t, outBufId>, Param>;
290	
291	public:
292	    using Type = UpdateOrPrepend_t<BufId2ParamMap, pos, NewItem>;
293	};
294	
295	template <typename T, typename = void>
296	struct GetTypeOrLike {
297	    using Type = T;
298	};
299	
300	template <typename T>
301	struct GetTypeOrLike<T, std::enable_if_t<IsLocalVar_v<T>>> {
302	    using Type = typename T::Like;
303	};
304	
305	template <typename T>
306	using GetTypeOrLike_t = typename GetTypeOrLike<T>::Type;
307	
308	template <
309	    int32_t combinedBufId, typename CurrentBind, typename OutBindLst, typename BufId2ParamMap, std::size_t localVarIdx>
310	__host_aicore__ constexpr decltype(auto) ReuseOrCreateLocalVar()
311	{
312	    // 1. if connect to output, use ParamOut.
313	    // 2. if bufId is reused, use corresponding Param or LocalVar
314	    // 3. Create a new LocalVar
315	    constexpr auto outPos = Find_v<IsInputOf<CurrentBind>::template Type, OutBindLst>;
316	    if constexpr (outPos < Size_v<OutBindLst>) {
317	        using CopyOutBind = Get_t<OutBindLst, outPos>;
318	        using ParamX = typename CopyOutBind::AssignedTo;
319	        using BufId2ParamMapNext = typename UpdateBufId2Param<BufId2ParamMap, combinedBufId, ParamX>::Type;
320	        return TypeList<
321	            ParamX, BufId2ParamMapNext, std::bool_constant<true>, std::integral_constant<std::size_t, localVarIdx>>{};
322	    } else {
323	        constexpr auto bufIds = DecodeBufferId<combinedBufId>::Value;
324	        constexpr auto outBufId = bufIds[0];
325	        constexpr auto pos = Find_v<BufId2ParamFinder<outBufId>::template Apply, BufId2ParamMap>;
326	        if constexpr (pos < Size_v<BufId2ParamMap>) {
327	            using ParamX = Get_t<Get_t<BufId2ParamMap, pos>, 1>;
328	            return TypeList<
329	                ParamX, BufId2ParamMap, std::bool_constant<false>, std::integral_constant<std::size_t, localVarIdx>>{};
330	        } else {
331	            using OriParamX = typename CurrentBind::AssignedTo;
332	            using Type = typename OriParamX::Type;
333	            using Like = GetTypeOrLike_t<OriParamX>;
334	            using NewLocalVar = LocalVar<localVarIdx, Type, Like>;
335	            using BufId2ParamMapNext = typename UpdateBufId2Param<BufId2ParamMap, outBufId, NewLocalVar>::Type;
336	            return TypeList<
337	                NewLocalVar, BufId2ParamMapNext, std::bool_constant<true>,
338	                std::integral_constant<std::size_t, localVarIdx + 1>>{};
339	        }
340	    }
341	};
342	
343	template <
344	    const int32_t* const* bufIds, typename BindLst, typename OutBindLst,
345	    /* Needs to update during each loop below */
346	    typename AssignLst = TypeList<>,                                         /* return */
347	    typename Bind2ParamMap = TypeList<>, typename Param2BufMap = TypeList<>, /* return */
348	    typename BufId2ParamMap = TypeList<>, std::size_t pos = 0, std::size_t localVarIdx = 1>
349	__host_aicore__ constexpr decltype(auto) Bind2OpAssign()
350	{
351	    if constexpr (pos < Size_v<BindLst>) {
352	        using B = Get_t<BindLst, pos>;
353	        using ParamX = typename B::AssignedTo;
354	        using Operation = typename B::Operation;
355	        constexpr auto pingId = bufIds[0][pos];
356	        constexpr auto pongId = bufIds[1][pos];
357	        if constexpr (B::isCopyXOp) {
358	            if constexpr (B::isCopyInOp) {
359	                using AssignLstNext = Append_t<AssignLst, Operation>;
360	                using Bind2ParamMapNext = Prepend_t<TypeList<B, ParamX>, Bind2ParamMap>;
361	                constexpr auto paramIdx = ParamX::number;
362	                using Param2BufMapNext =
363	                    Append_t<Param2BufMap, ParamBufIdMap<paramIdx, BufType::PARAM, pingId, pongId>>;
364	                using BufId2ParamMapNext = typename UpdateBufId2Param<BufId2ParamMap, pingId, ParamX>::Type;
365	                return Bind2OpAssign<
366	                    bufIds, BindLst, OutBindLst, AssignLstNext, Bind2ParamMapNext, Param2BufMapNext, BufId2ParamMapNext,
367	                    pos + 1, localVarIdx>();
368	            } else { // CopyOut
369	                using NewCopyOut = ReplaceOpArgs_t<Operation, BindAssignedToFinder<Bind2ParamMap>::template Type>;
370	                using AssignLstNext = Append_t<AssignLst, NewCopyOut>;
371	                return Bind2OpAssign<
372	                    bufIds, BindLst, OutBindLst, AssignLstNext, Bind2ParamMap, Param2BufMap, BufId2ParamMap, pos + 1,
373	                    localVarIdx>();
374	            }
375	        } else { // OpAssign
376	            using Result = decltype(ReuseOrCreateLocalVar<pingId, B, OutBindLst, BufId2ParamMap, localVarIdx>());
377	            using AssignLhs = Get_t<Result, 0>;
378	            using BufId2ParamMapNext = Get_t<Result, 1>;
379	            constexpr auto updateParam2BufMap = Get_t<Result, 2>::value;
380	            constexpr auto localVarIdxNext = Get_t<Result, 3>::value;
381	            using AssignRhs = ReplaceOpArgs_t<Operation, BindAssignedToFinder<Bind2ParamMap>::template Type>;
382	            using AssignLstNext = Append_t<AssignLst, OpAssign<AssignLhs, AssignRhs>>;
383	            using Bind2ParamMapNext = Prepend_t<TypeList<B, AssignLhs>, Bind2ParamMap>;
384	            if constexpr (updateParam2BufMap) {
385	                using Param2BufMapNext = Append_t<
386	                    Param2BufMap,
387	                    ParamBufIdMap<
388	                        AssignLhs::number, IsParam_v<AssignLhs> ? BufType::PARAM : BufType::LOCAL_VAR, pingId, pongId>>;
389	                return Bind2OpAssign<
390	                    bufIds, BindLst, OutBindLst, AssignLstNext, Bind2ParamMapNext, Param2BufMapNext, BufId2ParamMapNext,
391	                    pos + 1, localVarIdxNext>();
392	            } else {
393	                return Bind2OpAssign<
394	                    bufIds, BindLst, OutBindLst, AssignLstNext, Bind2ParamMapNext, Param2BufMap, BufId2ParamMapNext,
395	                    pos + 1, localVarIdxNext>();
396	            }
397	        }
398	    } else {
399	        return TypeList<AssignLst, Param2BufMap>{};
400	    }
401	}
402	
403	template <typename ExprList /*TypeList*/>
404	struct DagBase {
405	public:
406	    // Collect all parameters used (Usage = In/InOut/Out)
407	    // REMEMBER:
408	    //  Size_v<AllParams> <= Size_v<InParams> + Size_v<OutParams>
409	    using AllParams = Params_t<ExprList>;
410	    // Coolect CopyIn parameters (Usage = In/InOut)
411	    using InParams = Filter_t<IsInVar, AllParams>;
412	    // Collect CopyOut parameters (Usage = InOut/Out)
413	    using OutParams = Filter_t<IsOutVar, AllParams>;
414	};
415	
416	template <typename ExprList /*TypeList*/>
417	struct ManualDag : DagBase<ExprList> {
418	private:
419	    using Base = DagBase<ExprList>;
420	
421	public:
422	    using AllLocalVars = LocalVars_t<ExprList>;
423	    // TypeList of ParamBufIdMap
424	    using BufMap = typename GenerateBufferId<Size_v<typename Base::AllParams>, Size_v<AllLocalVars>>::Type;
425	    // Get a type list of type lists of three items:
426	    //      (Param, FirstUseConst, LastUseConst)
427	    using ParamUseList = Map_t<FirstAndLastUseFinder<ExprList>::template Type, typename Base::AllParams>;
428	    using LocalVarUseList = Map_t<FirstAndLastUseFinder<ExprList>::template Type, AllLocalVars>;
429	
430	private:
431	    // For each input Param in ParamUseList, add an OpCopyIn before its first use.
432	    // Reverse order makes the result "look" better.
433	    constexpr static auto result1 = ForEach(Reverse_t<ParamUseList>{}, CopyInInserter{}, ExprList{});
434	
435	    // For each output Param in ParamUseList, add an OpCopyOut after its last use.
436	    constexpr static auto result2 = ForEach(ParamUseList{}, CopyOutInserter{}, result1);
437	
438	public:
439	    using ExprListWithCopyX = decltype(result2);
440	};
441	
442	template <typename ExprList /*TypeList*/, MemLevel memOpt = MemLevel::LEVEL_0>
443	struct FullAutoDag {
444	public:
445	    // Handle Params with Usage=InOut and has been `OpAssign`ed Params.
446	    using NewExprList = typename InplaceParamsProcessor<ExprList>::Type;
447	    // Extract common members
448	    using Base = DagBase<NewExprList>;
449	    // Insert CopyIn & Append CopyOut
450	    using OriExprListWithCopyX = decltype(ForEach(typename Base::AllParams{}, AddCopyX{}, NewExprList{}));
451	    // For loop each OpCopyIn & OpAssign & OpCopyOut
452	    using BindList = decltype(ForEach(OriExprListWithCopyX{}, OpAssign2Bind{}, TypeList<>{}));
453	    // TypeList of CopyOut Bind.
454	    using OutList = GetLastN_t<BindList, Size_v<typename Base::OutParams>>;
455	    // Compute Order List
456	    using OrderdOps = Unique_t<decltype(ForEach(OutList{}, ExtractDependOps{}, TypeList<>{}))>;
457	    // Node information of current DAG.
458	    using FullNodeInfo = DagNodeInfo<OrderdOps, OutList>;
459	
460	    /***  Functions  ***/
461	private:
462	    template <typename NodeInfo>
463	    __host_aicore__ constexpr static MemLevel ChooseBufferLevel()
464	    {
465	        if constexpr (memOpt == MemLevel::LEVEL_0) {
466	            if constexpr ((NodeInfo::GetBufferNumLevel2()) <= MAX_BUFFER_NUMBER) {
467	                return MemLevel::LEVEL_2;
468	            } else if constexpr ((NodeInfo::GetBufferNumLevel1()) <= MAX_BUFFER_NUMBER) {
469	                return MemLevel::LEVEL_1;
470	            } else {
471	                return MemLevel::LEVEL_0;
472	            }
473	        } else {
474	            return memOpt;
475	        }
476	    }
477	
478	    // Get All Mte2 Num including Persist ones in @NodeInfo.
479	    template <typename NodeInfo>
480	    __host_aicore__ constexpr static std::size_t GetMte2Num()
481	    {
482	        if constexpr (ChooseBufferLevel<NodeInfo>() == MemLevel::LEVEL_0) {
483	            return (NodeInfo::GetGMCountBeforeFirstCalcNode()) + (NodeInfo::GetPersistMte2Num());
484	        } else {
485	            return NodeInfo::inSizeWoScalar;
486	        }
487	    }
488	
489	    // Get All Mte3 Num including Persist ones in @NodeInfo.
490	    template <typename NodeInfo>
491	    __host_aicore__ constexpr static std::size_t GetMte3Num()
492	    {
493	        constexpr auto persistMte3Num = NodeInfo::GetPersistMte3Num();
494	        if constexpr (ChooseBufferLevel<NodeInfo>() == MemLevel::LEVEL_0) {
495	            return (NodeInfo::GetFirstCopyOutNodeGMCount()) + persistMte3Num;
496	        } else {
497	            return (NodeInfo::GetLvl12Mte3Count()) + persistMte3Num;
498	        }
499	    }
500	
501	    // Get All Temp Buff Num including Persist ones in @NodeInfo.
502	    template <typename NodeInfo>
503	    __host_aicore__ constexpr static std::size_t GetTempBufNum()
504	    {
505	        constexpr auto bufferLvl = ChooseBufferLevel<NodeInfo>();
506	        constexpr auto persistTempCalcBufNum = NodeInfo::GetPersistTempCalcBufNum();
507	        if constexpr (bufferLvl == MemLevel::LEVEL_0) {
508	            return (NodeInfo::GetLvl0TmpSize()) + persistTempCalcBufNum;
509	        } else if constexpr (bufferLvl == MemLevel::LEVEL_1) {
510	            return (NodeInfo::GetLvl1TmpSize()) + persistTempCalcBufNum;
511	        } else {
512	            return (NodeInfo::GetTempCalcNodeSize()) + persistTempCalcBufNum;
513	        }
514	    }
515	
516	    // Get All Buff Num including Persist ones in @NodeInfo.
517	    template <typename NodeInfo>
518	    __host_aicore__ constexpr static uint32_t GetBufferNum()
519	    {
520	        constexpr auto bufferLvl = ChooseBufferLevel<NodeInfo>();
521	        if constexpr (bufferLvl == MemLevel::LEVEL_0) {
522	            return NodeInfo::GetBufferNumLevel0();
523	        } else if constexpr (bufferLvl == MemLevel::LEVEL_1) {
524	            return NodeInfo::GetBufferNumLevel1();
525	        } else { // bufferLvl == 2
526	            return NodeInfo::GetBufferNumLevel2();
527	        }
528	    }
529	
530	    template <typename NodeInfo>
531	    __host_aicore__ constexpr static const int32_t* const* GetBufferIds()
532	    {
533	        // |mte2|mte3|tmp|mte2|mte3|
534	        constexpr auto bufferLvl = ChooseBufferLevel<NodeInfo>();
535	        // Total Mte2 Count including Persist Mte2 in CopyInBrc
536	        constexpr auto mte2Count = GetMte2Num<NodeInfo>();
537	        // Total Mte3 Count including Persist Mte3 if CopyInBrc/VecBrc connects to CopyOut
538	        constexpr auto mte3Count = GetMte3Num<NodeInfo>();
539	        // Total Temp Buf Count including Cache Temp buf in CopyInBrc & VecBrc
540	        constexpr auto tempBufCount = GetTempBufNum<NodeInfo>();
541	        constexpr auto totalCount = (mte2Count + mte3Count) * BUF_PING_PONG + tempBufCount;
542	        static_assert(
543	            totalCount <= BUF_MAX_COUNT,
544	            "Buffer count exceeded 32. Please try to switch MemLevel to LEVEL_1 or LEVEL_0.");
545	        constexpr auto pongOffset = mte2Count + mte3Count + tempBufCount;
546	        // Persist Mte2 Count
547	        constexpr auto persistMte2Count = NodeInfo::GetPersistMte2Num();
548	        // Persist Mte3 Count
549	        constexpr auto persistMte3Count = NodeInfo::GetPersistMte3Num();
550	        // Persist Temp Buf Count
551	        constexpr auto persistTempBufCount = NodeInfo::GetPersistTempCalcBufNum();
552	        // Generate Buffer ID List.
553	        using PersistMte2Lst = typename GenerateBufferWrappers<
554	            persistMte2Count, BUF_MTE2,
555	            /*Offset=*/0>::Type;
556	        using Mte2Lst = typename GenerateBufferWrappers<
557	            mte2Count - persistMte2Count, BUF_MTE2,
558	            /*Offset=*/persistMte2Count>::Type;
559	        using PersistMte3Lst = typename GenerateBufferWrappers<
560	            persistMte3Count, BUF_MTE3,
561	            /*Offset=*/mte2Count>::Type;
562	        using Mte3Lst = typename GenerateBufferWrappers<
563	            mte3Count - persistMte3Count, BUF_MTE3,
564	            /*Offset=*/mte2Count + persistMte3Count>::Type;
565	        using PersistTmpLst = typename GenerateBufferWrappers<
566	            persistTempBufCount, BUF_TEMP,
567	            /*Offset=*/mte2Count + mte3Count>::Type;
568	        using TmpLst = typename GenerateBufferWrappers<
569	            tempBufCount - persistTempBufCount, BUF_TEMP,
570	            /*Offset=*/mte2Count + mte3Count + persistTempBufCount>::Type;
571	        using PongMte3Lst = std::conditional_t<
572	            bufferLvl == MemLevel::LEVEL_0,
573	            typename GenerateBufferWrappers<
574	                mte3Count - persistMte3Count, BUF_MTE3,
575	                /*Offset=*/totalCount - (mte3Count - persistMte3Count),
576	                /*Where=*/BUF_PONG>::Type,
577	            TypeList<>>;
578	        return GenerateBufferIdOrder<
579	            typename NodeInfo::SavedOpList, typename NodeInfo::SavedOutList,
580	            TypeList<PersistMte2Lst, Mte2Lst, PersistMte3Lst, Mte3Lst, PersistTmpLst, TmpLst, PongMte3Lst>, pongOffset,
581	            bufferLvl>();
582	    }
583	
584	private:
585	    using TmpRet = decltype(Bind2OpAssign<GetBufferIds<FullNodeInfo>(), OrderdOps, OutList>());
586	
587	public:
588	    // common members.
589	    using AllParams = typename Base::AllParams;
590	    using InParams = typename Base::InParams;
591	    using OutParams = typename Base::OutParams;
592	    // TypeList of rebuilt CopyIn / CopyOut / OpAssign
593	    using ExprListWithCopyX = Get_t<TmpRet, 0>;
594	    // TypeList of ParamBufIdMap
595	    using BufMap = Get_t<TmpRet, 1>;
596	    // TypeList of LocalVar
597	    using AllLocalVars = LocalVars_t<ExprListWithCopyX>;
598	    // Get a type list of type lists of three items:
599	    //      (Param, FirstUseConst, LastUseConst)
600	    using ParamUseList = Map_t<FirstAndLastUseFinder<ExprListWithCopyX>::template Type, AllParams>;
601	    using LocalVarUseList = Map_t<FirstAndLastUseFinder<ExprListWithCopyX>::template Type, AllLocalVars>;
602	};
603	
604	} // namespace Atvoss::Ele::Tile
605	#endif // ATVOSS_ELEWISE_GRAPH_DAG_H

